Read the DATA sheet and I2, split the data into header-delimited ranges, and for an empty I2 collapse each range to its header plus non-empty data rows while keeping one blank row between ranges and none after the last. Write the resulting rows into DATA!A1:E11 and clear the rest of A1:E19. This produces the desired first-sheet result with real dates and empty cells as None.

```python
import shutil
import openpyxl
from datetime import datetime

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["DATA"]
vws = vals["DATA"]

DATE_FORMATS = (
    "%Y-%m-%d %H:%M:%S",
    "%Y-%m-%d",
    "%Y/%m/%d %H:%M:%S",
    "%Y/%m/%d",
    "%m/%d/%Y %H:%M:%S",
    "%m/%d/%Y",
)

def norm(v):
    if isinstance(v, str):
        v = v.strip()
        if v == "":
            return None
    return v

def maybe_date(v):
    if isinstance(v, str):
        s = v.strip()
        for fmt in DATE_FORMATS:
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
    return v

def is_empty(row):
    return all(v is None for v in row)

def is_header(row):
    a, b = row[0], row[1]
    return (
        isinstance(a, str)
        and a.strip().lower() == "date"
        and isinstance(b, str)
        and b.strip().lower() == "id"
    )

rows = []
for r in range(1, 20):
    row = [norm(vws.cell(row=r, column=c).value) for c in range(1, 6)]
    row[0] = maybe_date(row[0])
    rows.append(row)

i2 = norm(vws["I2"].value)
headers = [i for i, row in enumerate(rows) if is_header(row)]
EMPTY = [None] * 5

if not headers:
    final_rows = [row for row in rows if not is_empty(row)]
else:
    if i2 is None:
        final_rows = []

        pre = [row for row in rows[:headers[0]] if not is_empty(row)]
        if pre:
            final_rows.extend(pre)
            final_rows.append(EMPTY)

        for bi, h in enumerate(headers):
            end = headers[bi + 1] - 1 if bi + 1 < len(headers) else len(rows) - 1
            block = rows[h:end + 1]

            data = [row for row in block[1:] if not is_empty(row)]
            final_rows.append(block[0])
            final_rows.extend(data)

            if bi != len(headers) - 1:
                final_rows.append(EMPTY)
    else:
        target = str(i2).strip()
        final_rows = []

        pre = [row for row in rows[:headers[0]] if not is_empty(row)]
        if pre:
            final_rows.extend(pre)
            final_rows.append(EMPTY)

        for bi, h in enumerate(headers):
            end = headers[bi + 1] - 1 if bi + 1 < len(headers) else len(rows) - 1
            block = rows[h:end + 1]

            data = [row for row in block[1:] if not is_empty(row)]
            matches = any(norm(row[1]) == target for row in data)

            if matches:
                final_rows.append(block[0])
                final_rows.extend(data)
                if bi != len(headers) - 1:
                    final_rows.append(EMPTY)
            else:
                final_rows.extend(block)

        while final_rows and is_empty(final_rows[-1]):
            final_rows.pop()

final_rows = final_rows[:19]

for r in range(1, 20):
    for c in range(1, 6):
        if r - 1 < len(final_rows):
            ws.cell(row=r, column=c).value = norm(final_rows[r - 1][c - 1])
        else:
            ws.cell(row=r, column=c).value = None

print("final_rows:", len(final_rows))
print("row1:", final_rows[0] if final_rows else None)
print("row2:", final_rows[1] if len(final_rows) > 1 else None)
print("row5:", final_rows[4] if len(final_rows) > 4 else None)

wb.save(OUT)
